import{_ as i,o as a,c as o,a2 as s}from"./chunks/framework.BN2sqjC1.js";const g=JSON.parse('{"title":"Processo di rilascio","description":"","frontmatter":{},"headers":[],"relativePath":"release/index.md","filePath":"release/README.md"}'),c={name:"release/index.md"};function l(n,e,t,r,d,p){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="processo-di-rilascio" tabindex="-1">Processo di rilascio <a class="header-anchor" href="#processo-di-rilascio" aria-label="Permalink to &quot;Processo di rilascio&quot;">​</a></h1><p>Dettagli tecnici e scelte: ADR-0023 e ADR-0031; verifiche: ADR-0036. Il workflow di rilascio è <code>release.yml</code> (l&#39;altro, <code>docs.yml</code>, pubblica solo il sito della documentazione: ADR-0067): costruisce e pubblica, <strong>non firma nulla</strong> e non esegue lint né test. Non c&#39;è un servizio di CI: le verifiche si fanno in locale con <code>task ci</code> prima del tag.</p><h2 id="versioni" tabindex="-1">Versioni <a class="header-anchor" href="#versioni" aria-label="Permalink to &quot;Versioni&quot;">​</a></h2><p>Versioni semver: <code>MAJOR.MINOR.PATCH</code>, con pre-release <code>-rc.N</code> / <code>-beta.N</code>. Il tag git è <code>vX.Y.Z[-pre]</code> (il workflow accetta anche <code>X.Y.Z[-pre]</code> senza <code>v</code>) ed è l&#39;unica fonte della versione: finisce nel binario (<code>-X main.Version</code>, schermata About), nell&#39;<code>Info.plist</code>, nelle risorse versione Windows, nell&#39;immagine OCI e nel chart Helm.</p><h2 id="prima-di-tagliare" tabindex="-1">Prima di tagliare <a class="header-anchor" href="#prima-di-tagliare" aria-label="Permalink to &quot;Prima di tagliare&quot;">​</a></h2><ol><li><code>task ci</code> verde in locale (ADR-0036): è l&#39;unico controllo prima della pubblicazione, il workflow non ne esegue.</li><li>Le suite lente elencate in <a href="./../dev-setup.html#verifiche"><code>docs/dev-setup.md</code></a> (integrazione del cloud, sync a due dispositivi e contract test, Playwright, cloud vero), <code>node scripts/pentest-inventory.mjs --check</code> e la checklist cross-OS (<code>docs/qa/</code>).</li><li><code>info.version</code> di <code>api/openapi.yaml</code> uguale alla versione del tag (poi <code>task gen-openapi</code>).</li><li>Note di rilascio: la sezione <em>Unreleased</em> di <code>CHANGELOG.md</code> diventa <code>## [X.Y.Z] - data</code> (se manca, <code>scripts/release/notes.sh</code> usa i messaggi di commit dall&#39;ultimo tag).</li></ol><h2 id="tagliare-un-rilascio" tabindex="-1">Tagliare un rilascio <a class="header-anchor" href="#tagliare-un-rilascio" aria-label="Permalink to &quot;Tagliare un rilascio&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tag</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -a</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> v1.0.0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Clarae notanda 1.0.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> origin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> v1.0.0</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # azione dell&#39;utente: gli agenti non fanno tag/push</span></span></code></pre></div><p>Il push del tag avvia <code>release.yml</code>, che:</p><ol><li>costruisce e pubblica su GHCR l&#39;<strong>immagine cloud</strong> multi-arch (<code>ghcr.io/&lt;owner&gt;/clarae-cloud:X.Y.Z</code>, più <code>X.Y</code> sulle versioni stabili) e il <strong>chart Helm</strong> come artefatto OCI (<code>oci://ghcr.io/&lt;owner&gt;/charts/clarae</code>);</li><li>costruisce gli <strong>installer desktop</strong>: macOS universale (<code>.dmg</code>), Windows amd64 (NSIS), Linux amd64 (<code>.deb</code> e AppImage);</li><li>crea e pubblica <strong>una</strong> GitHub Release con gli installer e <code>SHA256SUMS</code>, marcata <strong>prerelease</strong> se la versione ha un suffisso.</li></ol><p>Gli installer non sono firmati (Gatekeeper e SmartScreen avvisano al primo avvio) e l&#39;updater è compilato fuori dai binari (<code>ALLOW_UNSIGNED_UPDATES=1</code>): nessun manifest di aggiornamento. La prima volta i pacchetti GHCR sono privati: renderli pubblici (Package settings, Change visibility) se non devono richiedere un login.</p><p>Il workflow usa solo il <code>GITHUB_TOKEN</code> del run: <code>packages: write</code> per immagine e chart, <code>contents: write</code> per la Release; nessun segreto del repository (dettaglio in <a href="./secrets.html">secrets.md</a>). Le note della Release sono la sezione del <code>CHANGELOG.md</code> più i comandi <code>docker pull</code> e <code>helm install</code> e l&#39;avviso sugli installer non firmati.</p><h2 id="release-candidate" tabindex="-1">Release candidate <a class="header-anchor" href="#release-candidate" aria-label="Permalink to &quot;Release candidate&quot;">​</a></h2><p>Tag <code>v1.0.0-rc.1</code>: Release marcata <code>prerelease</code>, immagine senza il tag <code>X.Y</code>. Si promuove a stable solo con un nuovo tag <code>v1.0.0</code> costruito da zero (mai rinominare un RC: il binario porta la versione del tag).</p><h2 id="verificare-gli-artefatti" tabindex="-1">Verificare gli artefatti <a class="header-anchor" href="#verificare-gli-artefatti" aria-label="Permalink to &quot;Verificare gli artefatti&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sha256sum</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> SHA256SUMS</span></span></code></pre></div><h2 id="build-locali-senza-segreti" tabindex="-1">Build locali (senza segreti) <a class="header-anchor" href="#build-locali-senza-segreti" aria-label="Permalink to &quot;Build locali (senza segreti)&quot;">​</a></h2><ul><li><code>task release-desktop OS=darwin V=1.0.0-rc.1</code> (poi <code>scripts/release/package-macos.sh 1.0.0-rc.1</code>): <code>.app</code> universale e <code>.dmg</code> <strong>non firmato</strong>. Funziona su macOS; <code>OS=windows</code> (<code>ARCH=amd64|arm64</code>) produce l&#39;installer NSIS anche da macOS con <code>makensis</code> installato (non firmato, non provato su Windows). Lo script firma <code>clarae.exe</code> prima di impacchettarlo quando <code>CLARAE_SIGNTOOL_CMD</code> è impostata ed esegue <code>makensis</code> direttamente.</li><li>Come si costruisce (Wails v3, ADR-0051): <code>scripts/release/build-desktop.sh</code> chiama <code>scripts/build-desktop-bin.sh</code>, che esegue <code>go build -tags production</code> (più <code>gtk3</code> su Linux: GTK3 e WebKit2GTK 4.1) senza la CLI di Wails. Nel repository non cambia nulla: i template di <code>apps/desktop/build/</code> (<code>Info.plist</code>, <code>windows/info.json</code>, <code>windows/wails.exe.manifest</code>, <code>windows/installer/wails_tools.nsh</code>) sono resi da <code>scripts/release/render-assets.go</code> a partire da <code>apps/desktop/build/project.json</code> in una cartella temporanea. La CLI <code>wails3</code> serve solo per Windows (<code>wails3 generate syso</code> per icona, manifest e versione dell&#39;exe; <code>wails3 generate webview2bootstrapper</code> per il bootstrapper di WebView2): <code>task wails-cli</code> la installa alla versione di <code>apps/desktop/go.mod</code>.</li><li>Bootstrapper di WebView2: è la copia incorporata nel modulo Wails v3, quindi fissata da <code>go.sum</code>; il suo SHA-256 è anche in <code>scripts/release/checksums.sha256</code> e la build Windows si ferma se non coincide (dopo un aggiornamento di Wails: verificare il nuovo file e aggiornare la riga).</li><li>Guardia sulle build del frontend: con <code>--release</code> (che <code>task release-desktop</code> passa sempre), <code>scripts/release/build-desktop.sh</code> e <code>scripts/build-desktop-bin.sh</code> eseguono <code>scripts/release/check-editor-switches.sh</code>, che rifiuta <code>CLARAE_AI</code>, <code>CLARAE_COLLAB</code>, <code>CLARAE_E2E</code> e <code>CLARAE_DIST</code> se sono impostate (ADR-0050; <code>CLARAE_LIVE_ENGINE</code> non esiste più dal 2026-11-12, ADR-0049 A-W9), poi <code>scripts/release/check-dist.sh</code>, che fallisce se il <code>dist</code> costruito contiene il codice della collaborazione (<code>y-prosemirror</code>) o il finto binding delle prove, o se non contiene il chunk dell&#39;editor Live (<code>assets/MilkdownEditor-*.js</code>). Lo stesso fanno <code>task web-build</code> e il Dockerfile del cloud. Con <code>--release</code> sono rifiutati anche <code>--skip-frontend</code> e <code>--dev</code>.</li><li>Controllo dei tag: ogni binario di rilascio passa da <code>scripts/release/check-build-tags.sh</code> (<code>go version -m</code>): deve avere il tag <code>production</code> e nessuno fra <code>mcp</code>, <code>server</code> e <code>devtools</code> (il tag <code>mcp</code> apre un server su <code>127.0.0.1:9099</code>, <code>devtools</code> il web inspector). Su Linux si controlla anche che l&#39;eseguibile linki <code>libwebkit2gtk-4.1</code> e non GTK4.</li><li>Nomi degli artefatti (invariati rispetto a Wails v2; li leggono <code>release.yml</code>, i pacchetti e l&#39;updater): <code>clarae-&lt;versione&gt;-darwin-universal.dmg</code> (contiene <code>Clarae notanda.app</code>), <code>clarae-&lt;versione&gt;-windows-&lt;arch&gt;.exe</code> (installer NSIS <code>clarae-&lt;arch&gt;-installer.exe</code>, che installa <code>Clarae notanda.exe</code>), <code>clarae-&lt;versione&gt;-linux-&lt;arch&gt;.deb</code> e <code>.AppImage</code>. <code>LSMinimumSystemVersion</code> dell&#39;<code>Info.plist</code> è 13.0.0, il minimo di Go 1.27.</li><li>Immagine cloud: <code>task docker-build</code> (architettura locale) e <code>task docker-push</code> (multi-arch, richiede <code>docker login</code> e un builder buildx).</li><li><code>scripts/release/package-linux.sh</code> richiede <code>nfpm</code> e <code>appimagetool</code> su Linux.</li><li>Icone: generate dagli SVG di <code>assets/brand/</code> con <code>scripts/brand/gen-brand-assets.py</code> (vedi <code>assets/brand/README.md</code>). <code>build-desktop-bin.sh</code> copia <code>build/darwin/icon.icns</code> in <code>Contents/Resources/iconfile.icns</code> e passa <code>build/windows/icon.ico</code> a <code>wails3 generate syso</code>; il pacchetto Linux prende <code>build/linux/clarae.{png,svg}</code>.</li></ul><h2 id="da-riattivare" tabindex="-1">Da riattivare <a class="header-anchor" href="#da-riattivare" aria-label="Permalink to &quot;Da riattivare&quot;">​</a></h2><p>Tolti dalla pipeline nella 1.2.2 e da ripristinare in <code>release.yml</code> quando servono (segreti e variabili relativi in <a href="./secrets.html#da-riattivare">secrets.md</a>):</p><ul><li><strong>firma degli installer:</strong> Developer ID e notarizzazione per macOS, Authenticode per Windows (<code>clarae.exe</code> e installer); senza, gli avvisi del sistema operativo restano;</li><li><strong>immagine e chart:</strong> firma cosign keyless, SBOM e attestazioni di provenienza;</li><li><strong>aggiornamento automatico:</strong> manifest firmato (ed25519) per i canali stable e beta, updater compilato nei binari;</li><li><strong>verifiche automatiche:</strong> un workflow che esegua <code>task ci</code> su push e pull request (ADR-0036 lo lascia come opzione se i contributori aumentano);</li><li><strong>installer arm64:</strong> Windows arm64 (tolto nella 1.2.3) e Linux arm64 (serve un runner arm64).</li></ul><p>Le sezioni seguenti valgono solo quando il manifest di aggiornamento torna a essere firmato e pubblicato.</p><p><strong>Scadenza del manifest:</strong> <code>tools/release gen-manifest</code> firma un <code>expires_at</code> (default 30 giorni, opzione <code>-validity</code>, massimo accettato dai client 400 giorni). Un client che trova un manifest scaduto mostra un avviso invece di considerarlo aggiornato, così un canale congelato da un attaccante non passa inosservato. Prima della scadenza va pubblicato un manifest rifirmato con la stessa versione e <code>sequence</code> più alta.</p><h3 id="ruotare-la-chiave-di-aggiornamento" tabindex="-1">Ruotare la chiave di aggiornamento <a class="header-anchor" href="#ruotare-la-chiave-di-aggiornamento" aria-label="Permalink to &quot;Ruotare la chiave di aggiornamento&quot;">​</a></h3><p>La chiave pubblica è compilata nei client: una rotazione richiede che i client già installati si fidino della nuova chiave <strong>prima</strong> che la vecchia sia ritirata.</p><ol><li><code>bin/release gen-key</code>; conservare la nuova privata.</li><li>Rilasciare una versione di transizione <code>N</code> costruita con <code>UPDATE_PUBLIC_KEY</code> = nuova pubblica, ma il cui manifest è ancora firmato con la <strong>vecchia</strong> chiave (i client in campo la accettano). <code>release.yml</code> firma con <code>UPDATE_SIGNING_KEY</code>: tenere la vecchia in quel segreto per questo giro.</li><li>Quando la base installata è passata a <code>N</code> (o a una versione successiva), sostituire <code>UPDATE_SIGNING_KEY</code> con la nuova privata. I client <code>&lt; N</code> non riceveranno più aggiornamenti automatici: installazione manuale.</li><li>Distruggere la vecchia privata.</li></ol><p><strong>Compromissione della privata</strong>: chi la possiede può firmare manifest che tutti i client accettano; deve però controllare anche l&#39;hosting del canale (o il DNS) per farli arrivare, e l&#39;hash degli artefatti nel manifest è firmato, non sostituibile. Risposta: fermare subito la pubblicazione sul canale, ruotare come sopra distribuendo però la versione di transizione <strong>fuori canale</strong> (sito, e-mail), e pubblicare un avviso. Per questo la privata vive solo nei segreti del repository (ambiente protetto con approvazione consigliata) e in una copia offline cifrata.</p><h3 id="rollback-di-un-rilascio" tabindex="-1">Rollback di un rilascio <a class="header-anchor" href="#rollback-di-un-rilascio" aria-label="Permalink to &quot;Rollback di un rilascio&quot;">​</a></h3><p>Oggi, senza updater, un rilascio difettoso si corregge con una nuova versione di patch che gli utenti installano a mano. Con l&#39;updater attivo, i client non scendono mai di versione (regola anti-rollback, ADR-0023) e un rilascio difettoso si corregge con una nuova versione di patch. Per impedire che un&#39;installazione specifica continui a girare, alzare <code>min_version</code> nel manifest successivo (i client sotto la soglia vedono l&#39;aggiornamento come obbligatorio). Ripubblicare il vecchio manifest non ha effetto sui client già aggiornati e viene rifiutato come replay.</p>',29)])])}const h=i(c,[["render",l]]);export{g as __pageData,h as default};
